function Button({ children, onClick, variant = 'primary', className = '', disabled = false, testId }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'ghost' | 'outline' | 'dark'; className?: string; disabled?: boolean; testId?: string }) {
  const variants = {
    primary: 'bg-[#edae4a] text-[#17130e] hover:bg-[#ffc86a]',
    ghost: 'bg-white/[.08] text-[#f3f0e9] hover:bg-white/[.14]',
    outline: 'border border-white/20 text-[#f3f0e9] hover:border-[#edae4a]/70 hover:text-[#edae4a]',
    dark: 'bg-[#17191d] text-[#ddd9cf] hover:bg-[#22252b]',
  };
  return <button data-testid={testId} disabled={disabled} onClick={onClick} className={`inline-flex items-center justify-center gap-2 rounded-md px-4 py-2.5 text-[11px] font-extrabold uppercase tracking-[.12em] transition-colors disabled:pointer-events-none disabled:opacity-40 ${variants[variant]} ${className}`}>{children}</button>;
}

function IconButton({ label, children, onClick, active = false, className = '', testId }: { label: string; children: ReactNode; onClick?: () => void; active?: boolean; className?: string; testId?: string }) {
  return <button aria-label={label} title={label} data-testid={testId} onClick={onClick} className={`grid h-9 w-9 place-items-center rounded-md border transition-colors ${active ? 'border-[#edae4a]/50 bg-[#edae4a]/15 text-[#edae4a]' : 'border-transparent text-[#a6a9a8] hover:border-white/10 hover:bg-white/[.07] hover:text-white'} ${className}`}>{children}</button>;
}

