      {navItems.map(({ href, label, icon: Icon }) => <Link key={href} href={href} title={label} data-testid={`link-rail-${label.toLowerCase()}`} className={`relative grid h-10 w-10 place-items-center rounded-md transition-colors ${path === href || (href !== '/' && path.startsWith(href)) ? 'bg-white/[.09] text-white' : 'text-[#7f8383] hover:bg-white/[.06] hover:text-white'}`}>{(path === href || (href !== '/' && path.startsWith(href))) && <span className="absolute -left-[12px] h-5 w-[2px] bg-[#edae4a]" />}<Icon size={17} strokeWidth={1.8} /></Link>)}
