function GameCard({ game, onFavorite, onOpen, compact = false }: { game: Game; onFavorite: (id: string) => void; onOpen: (id: string) => void; compact?: boolean }) {
  return <div data-testid={`card-game-${game.id}`} className={`group relative overflow-hidden rounded-md border border-white/[.09] bg-[#15171b] transition-transform hover:-translate-y-1 hover:border-[#edae4a]/50 ${compact ? 'w-[230px] shrink-0' : ''}`}><button onClick={() => onOpen(game.id)} data-testid={`button-open-game-${game.id}`} className={`game-poster ${game.poster} relative block w-full text-left ${compact ? 'aspect-[1.58]' : 'aspect-[1.42]'}`}><div className="absolute inset-x-0 bottom-0 h-2/3 bg-gradient-to-t from-[#0b0d11] to-transparent" /><div className="absolute left-3 top-3 rounded bg-[#0b0d11]/60 px-2 py-1 font-mono-ui text-[8px] uppercase text-white/70">{game.status}</div><div className="absolute bottom-3 left-3"><div className="font-display text-xl font-semibold">{game.title}</div><div className="mt-1 font-mono-ui text-[8px] uppercase text-white/55">{game.genre}</div></div></button><button aria-label={`Favorite ${game.title}`} onClick={() => onFavorite(game.id)} data-testid={`button-favorite-${game.id}`} className={`absolute right-3 top-3 grid h-7 w-7 place-items-center rounded-full border backdrop-blur-md ${game.favorite ? 'border-[#edae4a]/50 bg-[#edae4a]/20 text-[#edae4a]' : 'border-white/20 bg-black/20 text-white/60'}`}><Heart size={13} fill={game.favorite ? 'currentColor' : 'none'} /></button><div className="flex items-center justify-between border-t border-white/[.07] px-3 py-2.5"><span className="flex items-center gap-1.5 text-[10px] text-white/50"><Star size={11} className="text-[#edae4a]" fill="currentColor" />{game.rating}</span>{game.progress > 0 && <span className="flex items-center gap-2"><span className="h-1 w-16 overflow-hidden rounded-full bg-white/10"><span className="block h-full bg-[#edae4a]" style={{ width: `${game.progress}%` }} /></span><span className="font-mono-ui text-[8px] text-white/45">{game.progress}%</span></span>}</div></div>;
}

function Home({ games, onFavorite, onOpen, onFriends }: { games: Game[]; onFavorite: (id: string) => void; onOpen: (id: string) => void; onFriends: () => void }) {
  const [campaignIndex, setCampaignIndex] = useState(0);
  const campaign = campaigns[campaignIndex];
  const game = games.find((item) => item.id === campaign.game) ?? games[0];
  return <PageFrame><section className={`hero-campaign ${campaign.art} min-h-[620px] md:min-h-[680px]`}><div className="hero-shape" /><div className="absolute right-5 top-20 z-10 hidden rounded-md border border-white/10 bg-[#121519]/65 px-3 py-2 text-[10px] text-white/65 backdrop-blur md:block"><span className="mr-2 inline-block h-1.5 w-1.5 rounded-full bg-[#6bcdb8]" /> 2 friends online <button onClick={onFriends} data-testid="button-open-friends-hero" className="ml-3 text-[#edae4a] hover:underline">View</button></div><div className="relative z-10 flex min-h-[620px] max-w-[650px] flex-col justify-end px-6 pb-14 md:min-h-[680px] md:px-12 md:pb-20"><motion.div key={campaignIndex} initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} className="max-w-xl"><div className="mb-4 flex items-center gap-3 font-mono-ui text-[9px] tracking-[.18em] text-[#edb04e]"><span className="h-px w-7 bg-[#edb04e]" />{campaign.eyebrow}</div><h1 className="font-display text-[clamp(3.2rem,7.2vw,7.1rem)] font-semibold leading-[.87] tracking-[-.08em] text-[#f5f3ec]">{campaign.title}</h1><p className="mt-6 max-w-md text-sm leading-6 text-white/62">{campaign.copy}</p><div className="mt-8 flex flex-wrap gap-3"><Button onClick={() => onOpen(game.id)} testId="button-campaign-primary"><Play size={14} fill="currentColor" /> {campaign.cta}</Button><Button variant="outline" onClick={() => onOpen(game.id)} testId="button-campaign-details">View world <ArrowRight size={14} /></Button></div></motion.div><div className="mt-9 flex items-center gap-3"><span className="font-mono-ui text-[9px] text-white/45">{String(campaignIndex + 1).padStart(2, '0')}</span>{campaigns.map((item, index) => <button key={item.game} aria-label={`Show campaign ${index + 1}`} onClick={() => setCampaignIndex(index)} data-testid={`button-campaign-${index + 1}`} className={`h-1 transition-all ${index === campaignIndex ? 'w-12 bg-[#edae4e]' : 'w-5 bg-white/30 hover:bg-white/60'}`} />)}<span className="font-mono-ui text-[9px] text-white/35">03</span></div></div><div className="absolute bottom-9 right-7 hidden items-center gap-3 font-mono-ui text-[9px] text-white/45 md:flex"><Volume2 size={14} /> CAMPAIGN AUDIO <span className="text-white/20">/</span> 01:38</div></section><div className="space-y-14 px-6 py-12 md:px-12 md:py-16"><section><SectionHeading eyebrow="YOUR WORLDS" title="Continue playing" action="Open library" href="/library" /><div className="flex gap-4 overflow-x-auto pb-3 thin-scroll">{games.map((item) => <GameCard key={item.id} game={item} onFavorite={onFavorite} onOpen={onOpen} compact />)}</div></section><section className="grid gap-5 lg:grid-cols-[1.28fr_.72fr]"><div className="relative overflow-hidden rounded-md border border-white/10 bg-[#15181b] p-7 md:p-10"><div className="absolute right-0 top-0 h-full w-1/2 bg-[radial-gradient(circle_at_70%_35%,rgba(107,203,211,.25),transparent_25%),linear-gradient(120deg,transparent,#17343a)]" /><div className="relative max-w-md"><div className="mb-3 flex items-center gap-2 font-mono-ui text-[9px] uppercase tracking-[.18em] text-[#edae4a]"><Sparkles size={13} /> Juhra weekly / 08.14</div><h2 className="font-display text-3xl font-semibold leading-tight tracking-[-.05em]">The unknown is a playable space.</h2><p className="mt-4 text-sm leading-6 text-white/48">Three worlds with no map, no compass, and no interest in telling you what to feel.</p><Link href="/store" data-testid="link-home-collection" className="mt-8 inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.15em] text-[#edae4e]">Explore the collection <ArrowRight size={14} /></Link></div></div><div className="rounded-md border border-white/10 bg-[#15181b] p-6"><div className="flex items-center justify-between"><span className="font-mono-ui text-[9px] uppercase tracking-[.18em] text-white/45">Your frequency</span><Activity size={15} className="text-[#6bcdb8]" /></div><div className="mt-8 flex h-20 items-end gap-1">{[34,55,43,75,62,82,49,68,91,57,72,63,84,48,67,78,54,88].map((height, index) => <span key={index} className="flex-1 bg-[#6bcdb8]/20"><span className="block bg-[#6bcdb8]/75" style={{ height: `${height}%` }} /></span>)}</div><div className="mt-5 flex items-baseline justify-between"><span className="font-display text-3xl font-semibold">18.4</span><span className="font-mono-ui text-[9px] text-white/35">HOURS THIS WEEK</span></div></div></section><section><SectionHeading eyebrow="DISPATCHES" title="What's new" action="See all news" href="/news" /><div className="grid gap-3 md:grid-cols-3">{dispatches.map((item) => <Link href="/news" key={item.title} data-testid={`link-dispatch-${item.title}`} className="group rounded-md border border-white/[.09] bg-[#15181b] p-3 hover:border-[#edae4a]/40"><div className={`hero-campaign ${item.art} relative h-32 rounded overflow-hidden`}><span className="absolute left-3 top-3 rounded border border-white/20 bg-black/20 px-2 py-1 font-mono-ui text-[8px]">{item.tag}</span></div><div className="px-2 pb-2 pt-4"><div className="font-mono-ui text-[9px] text-white/35">{item.date}</div><h3 className="mt-2 font-display text-lg font-semibold group-hover:text-[#edae4a]">{item.title}</h3><p className="mt-2 text-xs leading-5 text-white/43">{item.copy}</p></div></Link>)}</div></section></div></PageFrame>;
}

function SectionHeading({ eyebrow, title, action, href }: { eyebrow: string; title: string; action?: string; href?: string }) {
  return <div className="mb-6 flex items-end justify-between"><div><div className="mb-2 flex items-center gap-2 font-mono-ui text-[9px] uppercase tracking-[.2em] text-white/45"><span className="h-px w-5 bg-[#edae4a]" />{eyebrow}</div><h2 className="font-display text-2xl font-semibold tracking-[-.04em]">{title}</h2></div>{action && href && <Link href={href} data-testid={`link-section-${title.toLowerCase().replaceAll(' ', '-')}`} className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.13em] text-white/45 hover:text-[#edae4a]">{action}<ArrowRight size={14} /></Link>}</div>;
}

function Games({ games, onFavorite, onOpen }: { games: Game[]; onFavorite: (id: string) => void; onOpen: (id: string) => void }) {
  const [filter, setFilter] = useState('All');
  const [query, setQuery] = useState('');
  const filters = ['All', 'Narrative', 'Strategy', 'Exploration', 'RPG'];
  const filtered = games.filter((game) => (filter === 'All' || game.genre.toLowerCase().includes(filter.toLowerCase())) && game.title.toLowerCase().includes(query.toLowerCase()));
  return <PageFrame><div className="px-6 pb-16 pt-24 md:px-12 md:pt-28"><div className="mb-12 flex flex-col gap-5 border-b border-white/10 pb-8 md:flex-row md:items-end md:justify-between"><div><div className="mb-3 font-mono-ui text-[9px] uppercase tracking-[.2em] text-[#edae4a]">The catalogue / 04.28</div><h1 className="font-display text-5xl font-semibold tracking-[-.07em] md:text-7xl">Find a world<span className="text-[#edae4a]">.</span></h1><p className="mt-4 max-w-lg text-sm leading-6 text-white/45">Hand-picked signals for people who prefer a little mystery with their leisure.</p></div><div className="font-mono-ui text-[10px] text-white/35">04 WORLDS INDEXED <span className="mx-2 text-white/15">/</span> 02 UPDATES</div></div><section className="mb-14"><SectionHeading eyebrow="YOUR LAUNCHER" title="My games" /><div className="flex gap-5 overflow-x-auto pb-4 thin-scroll">{games.slice(0, 3).map((game) => <button key={game.id} onClick={() => onOpen(game.id)} data-testid={`button-my-game-${game.id}`} className="group flex min-w-[245px] items-center gap-3 text-left"><div className={`game-poster ${game.poster} h-[76px] w-[125px] shrink-0 rounded`} /><div><div className="font-display text-base font-semibold group-hover:text-[#edae4a]">{game.title}</div><div className="mt-1 font-mono-ui text-[8px] uppercase text-white/35">{game.status}</div></div></button>)}</div></section><section><div className="mb-7 flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div className="flex flex-wrap gap-1">{filters.map((item) => <button key={item} onClick={() => setFilter(item)} data-testid={`button-filter-${item.toLowerCase()}`} className={`rounded px-3 py-2 font-mono-ui text-[9px] uppercase transition-colors ${filter === item ? 'bg-[#edae4a] text-[#17130e]' : 'border border-white/10 text-white/45 hover:border-white/25 hover:text-white'}`}>{item}</button>)}</div><label className="flex h-10 items-center gap-2 rounded border border-white/10 bg-[#15181b] px-3 lg:w-64"><Search size={14} className="text-white/35" /><input value={query} onChange={(event) => setQuery(event.target.value)} data-testid="input-game-search" placeholder="Search catalogue" className="w-full bg-transparent text-xs outline-none placeholder:text-white/25" /></label></div>{filtered.length ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{filtered.map((game) => <GameCard key={game.id} game={game} onFavorite={onFavorite} onOpen={onOpen} />)}</div> : <div className="rounded-md border border-dashed border-white/15 py-24 text-center"><Compass size={25} className="mx-auto mb-4 text-white/25" /><h3 className="font-display text-xl">No worlds match that signal</h3><Button variant="outline" className="mt-5" onClick={() => { setFilter('All'); setQuery(''); }} testId="button-reset-filter">Reset filters</Button></div>}</section></div></PageFrame>;
}

function GameDetails({ game, onBack, onFavorite, notify }: { game: Game; onBack: () => void; onFavorite: (id: string) => void; notify: (message: string) => void }) {
  const [tab, setTab] = useState('Overview');
  const [installed, setInstalled] = useState(game.status !== 'New');
  const tabs = ['Overview', 'Patch notes', 'Community', 'Media'];
  const newsCards = [{ tag: 'FIELD NOTES', title: 'The first room below', art: game.poster }, { tag: 'UPDATE', title: 'A new route opens', art: game.poster }, { tag: 'STUDIO', title: 'Making the impossible quiet', art: game.poster }];
  return <PageFrame><section className={`hero-campaign ${game.id === 'ashen-reach' ? 'hero-art-ashen' : game.id === 'red-assembly' ? 'hero-art-red' : game.id === 'blue-echo' ? 'hero-art-blue' : 'hero-art-palace'} min-h-[720px]`}><div className="hero-shape" /><button onClick={onBack} data-testid="button-game-back" className="absolute left-6 top-24 z-10 flex items-center gap-2 font-mono-ui text-[9px] uppercase text-white/55 hover:text-white md:left-12"><ChevronLeft size={14} /> All games</button><div className="absolute left-6 top-24 z-10 hidden font-display text-xl font-bold tracking-[.16em] md:left-24 md:block">{game.title.toUpperCase()}</div><div className="absolute left-1/2 top-[76px] z-10 hidden -translate-x-1/2 gap-1 rounded-full border border-white/10 bg-[#141619]/70 p-1 backdrop-blur md:flex">{tabs.map((item) => <button key={item} onClick={() => setTab(item)} data-testid={`button-game-tab-${item.toLowerCase().replaceAll(' ', '-')}`} className={`rounded-full px-4 py-2 font-mono-ui text-[9px] transition-colors ${tab === item ? 'bg-white text-[#17191d]' : 'text-white/55 hover:text-white'}`}>{item}</button>)}</div><div className="relative z-10 flex min-h-[720px] flex-col justify-end px-6 pb-12 md:px-12 md:pb-16"><div className="max-w-[500px]"><div className="mb-4 font-mono-ui text-[9px] uppercase tracking-[.2em] text-[#edae4a]">{tab} · {game.meta}</div><h1 className="font-display text-6xl font-semibold leading-[.9] tracking-[-.08em] md:text-8xl">{game.title}<span className="text-[#edae4a]">.</span></h1><p className="mt-5 max-w-md text-sm leading-6 text-white/60">{game.subtitle}. An original Juhra world shaped by memory, weather, and the decisions left behind.</p><div className="mt-8 flex items-center gap-3"><Button onClick={() => { if (!installed) { setInstalled(true); notify(`${game.title} is queued for install`); } else notify(`Launching ${game.title}`); }} testId="button-game-primary">{installed ? <><Play size={14} fill="currentColor" /> Play now</> : <><Download size={14} /> Install</>}</Button><IconButton label="Favorite game" active={game.favorite} onClick={() => onFavorite(game.id)} testId="button-game-detail-favorite"><Heart size={16} fill={game.favorite ? 'currentColor' : 'none'} /></IconButton><Button variant="outline" onClick={() => notify('Invite link copied to clipboard')} testId="button-game-share">Share</Button></div></div><div className="mt-10 flex gap-3 overflow-x-auto pb-2 md:absolute md:bottom-12 md:right-10 md:mt-0 md:w-[51%]">{newsCards.map((card) => <button key={card.title} onClick={() => notify(`${card.title} opened`)} data-testid={`button-game-news-${card.title}`} className="group min-w-[180px] overflow-hidden rounded-md border border-white/15 bg-[#111419]/75 text-left backdrop-blur"><div className={`game-poster ${card.art} h-24`} /><div className="p-3"><div className="font-mono-ui text-[8px] text-[#edae4a]">{card.tag}</div><div className="mt-2 text-xs font-bold group-hover:text-[#edae4a]">{card.title}</div></div></button>)}</div></div></section></PageFrame>;
}

function Library({ games, onFavorite, onOpen, notify }: { games: Game[]; onFavorite: (id: string) => void; onOpen: (id: string) => void; notify: (message: string) => void }) {
  const [tab, setTab] = useState<'Installed' | 'Favorites'>('Installed');
  const visible = tab === 'Installed' ? games.filter((game) => game.status !== 'Wishlist') : games.filter((game) => game.favorite);
  return <PageFrame><div className="px-6 pb-16 pt-24 md:px-12 md:pt-28"><div className="mb-10 flex items-end justify-between border-b border-white/10 pb-8"><div><div className="mb-3 font-mono-ui text-[9px] uppercase tracking-[.2em] text-[#edae4a]">Personal archive</div><h1 className="font-display text-5xl font-semibold tracking-[-.07em] md:text-7xl">Your library<span className="text-[#edae4a]">.</span></h1></div><div className="hidden text-right md:block"><div className="font-display text-3xl font-semibold">{String(games.length).padStart(2, '0')}</div><div className="font-mono-ui text-[9px] text-white/35">WORLDS COLLECTED</div></div></div><div className="mb-7 flex items-center justify-between"><div className="flex gap-5 font-mono-ui text-[10px] uppercase"><button onClick={() => setTab('Installed')} data-testid="button-library-installed" className={`border-b pb-2 ${tab === 'Installed' ? 'border-[#edae4a] text-[#edae4a]' : 'border-transparent text-white/40'}`}>Installed</button><button onClick={() => setTab('Favorites')} data-testid="button-library-favorites" className={`border-b pb-2 ${tab === 'Favorites' ? 'border-[#edae4a] text-[#edae4a]' : 'border-transparent text-white/40'}`}>Favorites</button></div><button onClick={() => notify('Library sorted by recent activity')} data-testid="button-library-sort" className="flex items-center gap-2 font-mono-ui text-[9px] text-white/40"><SlidersHorizontal size={14} /> Sort: Recent <ChevronDown size={13} /></button></div><div className="space-y-3">{visible.map((game, index) => <div key={game.id} className="grid gap-4 rounded-md border border-white/[.09] bg-[#15181b] p-3 transition-colors hover:border-[#edae4a]/35 md:grid-cols-[200px_1fr_auto] md:items-center"><button onClick={() => onOpen(game.id)} data-testid={`button-library-open-${game.id}`} className={`game-poster ${game.poster} aspect-[1.58] overflow-hidden rounded text-left`} /><div className="px-1"><div className="flex items-start justify-between"><div><h3 className="font-display text-xl font-semibold">{game.title}</h3><p className="mt-1 text-xs text-white/42">{game.subtitle}</p></div><IconButton label={`Favorite ${game.title}`} active={game.favorite} onClick={() => onFavorite(game.id)} testId={`button-library-favorite-${game.id}`}><Heart size={15} fill={game.favorite ? 'currentColor' : 'none'} /></IconButton></div><div className="mt-5 flex max-w-md items-center gap-3"><div className="h-1 flex-1 rounded-full bg-white/10"><div className="h-full rounded-full bg-[#edae4a]" style={{ width: `${game.progress || 100}%` }} /></div><span className="font-mono-ui text-[9px] text-white/40">{game.progress || 100}%</span></div><div className="mt-3 flex gap-4 font-mono-ui text-[9px] text-white/30"><span>{game.meta}</span><span>{game.hours} PLAYED</span></div></div><div className="flex items-center gap-2 md:flex-col"><Button onClick={() => { onOpen(game.id); notify(`Preparing ${game.title}`); }} testId={`button-play-library-${game.id}`} className="w-full md:w-auto"><Play size={13} fill="currentColor" /> Play</Button><button onClick={() => notify(`${game.title} options opened`)} data-testid={`button-library-more-${game.id}`} className="p-2 text-white/35 hover:text-white"><MoreHorizontal size={17} /></button></div></div>)}{!visible.length && <div className="rounded-md border border-dashed border-white/15 py-24 text-center"><Heart size={25} className="mx-auto mb-4 text-white/25" /><h3 className="font-display text-xl">Nothing saved here yet</h3></div>}</div></div></PageFrame>;
}

function StorePage({ games, onOpen, notify }: { games: Game[]; onOpen: (id: string) => void; notify: (message: string) => void }) {
  const [added, setAdded] = useState<string[]>([]);
  return <PageFrame><div className="px-6 pb-16 pt-24 md:px-12 md:pt-28"><div className="mb-10 flex items-end justify-between border-b border-white/10 pb-8"><div><div className="mb-3 font-mono-ui text-[9px] uppercase tracking-[.2em] text-[#edae4a]">The exchange / carefully chosen</div><h1 className="font-display text-5xl font-semibold tracking-[-.07em] md:text-7xl">Acquire a signal<span className="text-[#edae4a]">.</span></h1></div><button onClick={() => notify(`${added.length} item${added.length === 1 ? '' : 's'} in cart`)} data-testid="button-store-cart" className="flex items-center gap-2 rounded border border-white/15 px-4 py-3 text-[10px] uppercase tracking-[.14em] text-white/65 hover:border-[#edae4a]/60 hover:text-[#edae4a]"><ShoppingBag size={14} /> Cart <span className="font-mono-ui text-[#edae4a]">{added.length}</span></button></div><div className="mb-8 flex gap-5 border-b border-white/10 pb-3 font-mono-ui text-[10px] uppercase"><button data-testid="button-store-featured" className="border-b border-[#edae4a] pb-3 text-[#edae4a]">Featured</button><button onClick={() => notify('Collections are curated weekly')} data-testid="button-store-collections" className="pb-3 text-white/35 hover:text-white">Collections</button><button onClick={() => notify('Your wishlist is synced')} data-testid="button-store-wishlist" className="pb-3 text-white/35 hover:text-white">Wishlist</button></div><div className="grid gap-5 lg:grid-cols-3">{games.map((game, index) => <div key={game.id} className={`rounded-md border border-white/[.09] bg-[#15181b] p-3 ${index === 0 ? 'lg:col-span-2 lg:row-span-2' : ''}`}><button onClick={() => onOpen(game.id)} data-testid={`button-store-open-${game.id}`} className={`game-poster ${game.poster} relative block w-full overflow-hidden rounded ${index === 0 ? 'aspect-[1.75]' : 'aspect-[1.55]'}`}><div className="absolute inset-x-0 bottom-0 h-2/3 bg-gradient-to-t from-[#090b0d] to-transparent" /><div className="absolute bottom-4 left-4 font-display text-2xl font-semibold">{game.title}</div></button><div className="flex items-center justify-between px-1 pb-1 pt-4"><div><div className="font-mono-ui text-[9px] text-white/35">{game.meta}</div><div className="mt-1 font-display text-base">{index === 0 ? 'Included with Juhra+' : `€${index === 1 ? '24.80' : '19.40'}`}</div></div><Button variant={added.includes(game.id) ? 'dark' : 'outline'} disabled={added.includes(game.id)} onClick={() => { setAdded([...added, game.id]); notify(`${game.title} added to your library`); }} testId={`button-buy-${game.id}`}>{added.includes(game.id) ? <><Check size={13} /> Added</> : <><Plus size={13} /> Add</>}</Button></div></div>)}</div></div></PageFrame>;
}

function NewsPage() {
  const [active, setActive] = useState('All dispatches');
  const [opened, setOpened] = useState('');
  const tabs = ['All dispatches', 'Field notes', 'Studio', 'Signal'];
  const list = active === 'All dispatches' ? dispatches : dispatches.filter((item) => item.tag.toLowerCase().includes(active.split(' ')[0].toLowerCase()));
  return <PageFrame><div className="px-6 pb-16 pt-24 md:px-12 md:pt-28"><div className="mb-10 border-b border-white/10 pb-8"><div className="mb-3 font-mono-ui text-[9px] uppercase tracking-[.2em] text-[#edae4a]">Juhra editorial / live</div><h1 className="font-display text-5xl font-semibold tracking-[-.07em] md:text-7xl">Dispatches<span className="text-[#edae4a]">.</span></h1></div><div className="mb-8 flex flex-wrap gap-5 font-mono-ui text-[10px] uppercase">{tabs.map((tab) => <button key={tab} onClick={() => setActive(tab)} data-testid={`button-news-${tab.toLowerCase().replaceAll(' ', '-')}`} className={`border-b pb-2 ${active === tab ? 'border-[#edae4a] text-[#edae4a]' : 'border-transparent text-white/40 hover:text-white'}`}>{tab}</button>)}</div><div className="grid gap-4 md:grid-cols-2">{list.map((item, index) => <article key={item.title} className={`group rounded-md border border-white/[.09] bg-[#15181b] p-3 ${index === 0 ? 'md:col-span-2 md:grid md:grid-cols-[1.15fr_.85fr]' : ''}`}><div className={`hero-campaign ${item.art} relative h-52 overflow-hidden rounded ${index === 0 ? 'md:h-full md:min-h-[300px]' : ''}`} /><div className="p-4 md:p-6"><div className="font-mono-ui text-[9px] text-[#edae4a]">{item.tag} <span className="mx-2 text-white/20">/</span> {item.date}</div><h2 className="mt-3 font-display text-2xl font-semibold group-hover:text-[#edae4a]">{item.title}</h2><p className="mt-3 max-w-md text-sm leading-6 text-white/45">{item.copy}</p><button onClick={() => setOpened(opened === item.title ? '' : item.title)} data-testid={`button-read-${item.title}`} className="mt-7 inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.14em] text-white/65 hover:text-[#edae4a]">{opened === item.title ? 'Close dispatch' : 'Read dispatch'} <ArrowRight size={14} /></button>{opened === item.title && <p className="mt-4 border-l border-[#edae4a] pl-3 text-xs leading-5 text-white/55">The full dispatch is now open in your reading queue. Save this signal and return to it from your profile.</p>}</div></article>)}</div></div></PageFrame>;
}

function ProfilePage({ notify }: { notify: (message: string) => void }) {
  return <PageFrame><div className="mx-auto max-w-5xl px-6 pb-16 pt-24 md:px-12 md:pt-28"><div className="mb-10 flex items-center gap-5 border-b border-white/10 pb-10"><span className="grid h-20 w-20 place-items-center rounded-xl bg-[#edae4a] font-display text-2xl font-bold text-[#17130e]">AR</span><div><div className="font-mono-ui text-[9px] uppercase tracking-[.2em] text-[#edae4a]">Player profile / level 18</div><h1 className="mt-2 font-display text-5xl font-semibold">Ari Rhee<span className="text-[#edae4a]">.</span></h1><p className="mt-2 text-sm text-white/45">Playing quietly since the first signal.</p></div></div><div className="grid gap-5 md:grid-cols-3"><div className="rounded-md border border-white/10 bg-[#15181b] p-6"><div className="font-mono-ui text-[9px] text-white/40">WORLDS VISITED</div><div className="mt-4 font-display text-4xl">14</div><div className="mt-2 text-xs text-white/40">Across four Juhra worlds</div></div><div className="rounded-md border border-white/10 bg-[#15181b] p-6"><div className="font-mono-ui text-[9px] text-white/40">TOTAL TIME</div><div className="mt-4 font-display text-4xl">137.3h</div><div className="mt-2 text-xs text-white/40">18.4h this week</div></div><div className="rounded-md border border-white/10 bg-[#15181b] p-6"><div className="font-mono-ui text-[9px] text-white/40">ACHIEVEMENTS</div><div className="mt-4 font-display text-4xl">27</div><div className="mt-2 text-xs text-white/40">Three rare discoveries</div></div></div><section className="mt-8 rounded-md border border-white/10 bg-[#15181b] p-6"><div className="flex items-center justify-between"><h2 className="font-display text-2xl font-semibold">Recent activity</h2><Button variant="outline" onClick={() => notify('Profile sharing link copied')} testId="button-share-profile">Share profile</Button></div>{['Completed Chapter 04 in Ashen Reach', 'Added Blue Echo to favorites', 'Joined the Juhra weekly collection'].map((item, index) => <div key={item} className="flex items-center gap-4 border-t border-white/[.07] py-4"><span className="grid h-8 w-8 place-items-center rounded bg-white/[.06] text-[#edae4a]">{index === 0 ? <Check size={14} /> : index === 1 ? <Heart size={14} /> : <Sparkles size={14} />}</span><span className="text-sm text-white/70">{item}</span><span className="ml-auto font-mono-ui text-[9px] text-white/30">{index + 1}D AGO</span></div>)}</section></div></PageFrame>;
}

function SettingsPage({ notify }: { notify: (message: string) => void }) {
  const [audio, setAudio] = useState(true);
  const [notifications, setNotifications] = useState(true);
  return <PageFrame><div className="mx-auto max-w-4xl px-6 pb-16 pt-24 md:px-12 md:pt-28"><div className="mb-10 border-b border-white/10 pb-8"><div className="mb-3 font-mono-ui text-[9px] uppercase tracking-[.2em] text-[#edae4a]">Launcher controls</div><h1 className="font-display text-5xl font-semibold tracking-[-.07em]">Settings<span className="text-[#edae4a]">.</span></h1></div><div className="space-y-3">{[{ label: 'Interface audio', copy: 'Play sounds for navigation and launch events.', value: audio, set: setAudio }, { label: 'Social notifications', copy: 'Let friends know when you come online.', value: notifications, set: setNotifications }].map((item) => <div key={item.label} className="flex items-center justify-between rounded-md border border-white/10 bg-[#15181b] p-5"><div><h2 className="text-sm font-bold">{item.label}</h2><p className="mt-1 text-xs text-white/40">{item.copy}</p></div><button onClick={() => { item.set(!item.value); notify(`${item.label} ${item.value ? 'disabled' : 'enabled'}`); }} data-testid={`button-toggle-${item.label.toLowerCase().replace(' ', '-')}`} className={`relative h-6 w-11 rounded-full transition-colors ${item.value ? 'bg-[#edae4a]' : 'bg-white/15'}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-[#17130e] transition-transform ${item.value ? 'translate-x-6' : 'translate-x-1'}`} /></button></div>)}<div className="rounded-md border border-white/10 bg-[#15181b] p-5"><div className="flex items-center gap-3"><Shield size={18} className="text-[#6bcdb8]" /><div><h2 className="text-sm font-bold">Account security</h2><p className="mt-1 text-xs text-white/40">Two-step verification is enabled for Ari Rhee.</p></div><span className="ml-auto font-mono-ui text-[9px] text-[#6bcdb8]">PROTECTED</span></div></div><div className="flex justify-end pt-4"><Button onClick={() => notify('Settings saved')} testId="button-save-settings">Save changes</Button></div></div></div></PageFrame>;
}

function DownloadsPage({ notify }: { notify: (message: string) => void }) {
  const [paused, setPaused] = useState(false);
  return <PageFrame><div className="mx-auto max-w-4xl px-6 pb-16 pt-24 md:px-12 md:pt-28"><div className="mb-10 border-b border-white/10 pb-8"><div className="mb-3 font-mono-ui text-[9px] uppercase tracking-[.2em] text-[#edae4a]">System queue / 01 active</div><h1 className="font-display text-5xl font-semibold tracking-[-.07em]">Downloads<span className="text-[#edae4a]">.</span></h1></div><div className="rounded-md border border-[#edae4a]/35 bg-[#171a1e] p-6"><div className="flex items-start gap-4"><div className="grid h-12 w-12 place-items-center rounded-md bg-[#edae4a]/15 text-[#edae4a]"><CloudDownload size={22} /></div><div className="flex-1"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-semibold">Blue Echo</h2><span className="font-mono-ui text-[10px] text-[#edae4a]">{paused ? 'PAUSED' : '68%'}</span></div><p className="mt-1 text-xs text-white/40">12.4 GB of 18 GB · Estimated 4 min remaining</p><div className="mt-5 h-2 overflow-hidden rounded-full bg-white/10"><div className={`h-full bg-[#edae4a] transition-all ${paused ? 'w-[68%]' : 'w-[72%]'}`} /></div><div className="mt-5 flex gap-2"><Button onClick={() => { setPaused(!paused); notify(paused ? 'Download resumed' : 'Download paused'); }} testId="button-download-pause">{paused ? <><Play size={13} fill="currentColor" /> Resume</> : <><Pause size={13} /> Pause</>}</Button><Button variant="outline" onClick={() => notify('Download cancelled')} testId="button-download-cancel">Cancel</Button></div></div></div></div><div className="mt-8"><SectionHeading eyebrow="RECENTLY COMPLETE" title="Update history" />{['Ashen Reach · 1.8.2', 'Red Assembly · 2.4.0', 'Juhra launcher · 0.9.7'].map((item) => <div key={item} className="flex items-center gap-3 border-b border-white/[.07] py-4"><Check size={15} className="text-[#6bcdb8]" /><span className="text-sm text-white/65">{item}</span><span className="ml-auto font-mono-ui text-[9px] text-white/30">COMPLETE</span></div>)}</div></div></PageFrame>;
}

function PageFrame({ children }: { children: ReactNode }) { return <main className="animate-rise">{children}</main>; }

function AppContent() {
  const [location, setLocation] = useLocation();
  const [games, setGames] = useState(initialGames);
  const [searchOpen, setSearchOpen] = useState(false);
  const [friendsOpen, setFriendsOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [toast, setToast] = useState('');
  const currentPath = location || '/';
  const activeTitle = currentPath === '/' ? 'Home' : currentPath.slice(1).split('/')[0].replace('-', ' ');
  const selectedGame = useMemo(() => { const id = currentPath.split('/')[2]; return games.find((game) => game.id === id) ?? games[0]; }, [currentPath, games]);
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2300); };
  const favorite = (id: string) => setGames((items) => items.map((game) => game.id === id ? { ...game, favorite: !game.favorite } : game));
  const openGame = (id: string) => setLocation(`/games/${id}`);
  let page: ReactNode;
  if (currentPath === '/' || currentPath === '') page = <Home games={games} onFavorite={favorite} onOpen={openGame} onFriends={() => setFriendsOpen(true)} />;
  else if (currentPath === '/games') page = <Games games={games} onFavorite={favorite} onOpen={openGame} />;
  else if (currentPath.startsWith('/games/')) page = <GameDetails game={selectedGame} onBack={() => setLocation('/games')} onFavorite={favorite} notify={notify} />;
  else if (currentPath === '/library') page = <Library games={games} onFavorite={favorite} onOpen={openGame} notify={notify} />;
  else if (currentPath === '/store') page = <StorePage games={games} onOpen={openGame} notify={notify} />;
  else if (currentPath === '/news') page = <NewsPage />;
  else if (currentPath === '/profile') page = <ProfilePage notify={notify} />;
  else if (currentPath === '/settings') page = <SettingsPage notify={notify} />;
  else if (currentPath === '/downloads') page = <DownloadsPage notify={notify} />;
  else page = <Home games={games} onFavorite={favorite} onOpen={openGame} onFriends={() => setFriendsOpen(true)} />;
  return <div className="juhra-shell juhra-noise min-h-[100dvh]"><Rail path={currentPath} onSearch={() => setSearchOpen(true)} onFriends={() => setFriendsOpen(true)} /><TopChrome title={activeTitle} onProfile={() => setProfileOpen((value) => !value)} onFriends={() => setFriendsOpen(true)} onSearch={() => setSearchOpen(true)} /><div className="min-h-[100dvh] pb-16 md:ml-[64px] md:pb-0">{page}</div><div className="fixed bottom-0 left-0 right-0 z-40 flex h-16 items-center justify-around border-t border-white/10 bg-[#121418]/95 backdrop-blur-md md:hidden">{navItems.slice(0, 5).map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-mobile-${label.toLowerCase()}`} className={`grid h-10 w-12 place-items-center rounded ${currentPath === href ? 'text-[#edae4a]' : 'text-white/40'}`}><Icon size={17} /><span className="mt-0.5 font-mono-ui text-[7px]">{label}</span></Link>)}</div><ProfileMenu open={profileOpen} close={() => setProfileOpen(false)} navigate={setLocation} /><FriendsPanel open={friendsOpen} close={() => setFriendsOpen(false)} /><SearchOverlay open={searchOpen} close={() => setSearchOpen(false)} games={games} onOpen={openGame} />{toast && <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} className="fixed bottom-6 left-1/2 z-[90] -translate-x-1/2 rounded-md border border-[#edae4a]/40 bg-[#1b1e22] px-5 py-3 text-xs font-semibold shadow-2xl">{toast}</motion.div>}</div>;
}

function App() {
  return <ErrorBoundary><QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter><AppContent /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider></ErrorBoundary>;
}

export { default } from './JuhraReferenceClient';